**config.go**

```go
package lesson

import (
	"fmt"
	"strconv"
	"strings"
)

type Config struct {
	Host string
	Port int
}

func ParseConfig(value string) (Config, error) {
	host, rawPort, ok := strings.Cut(value, ":")
	if !ok || host == "" {
		return Config{}, fmt.Errorf("invalid config %q", value)
	}
	port, err := strconv.Atoi(rawPort)
	if err != nil {
		return Config{}, fmt.Errorf("invalid port: %w", err)
	}
	return Config{Host: host, Port: port}, nil
}
```

**config_test.go**

```go
package lesson

import "testing"

func TestParseConfig(t *testing.T) {
	got, err := ParseConfig("api:8080")
	if err != nil {
		t.Fatalf("ParseConfig returned an error: %v", err)
	}
	if got.Host != "api" {
		t.Errorf("Host = %q; want api", got.Host)
	}
	if got.Port != 8080 {
		t.Errorf("Port = %d; want 8080", got.Port)
	}
}
```

**Run it**

```bash
go test ./...
```

The parse result is a prerequisite, while its two fields are independent observations. The test therefore stops once, then can report both field mismatches.

**user.go**

```go
package lesson

type User struct {
	Name   string
	Active bool
}

func FindUser(users map[int]User, id int) (*User, bool) {
	user, ok := users[id]
	if !ok {
		return nil, false
	}
	return &user, true
}
```

**user_test.go**

```go
package lesson

import "testing"

func TestFindUser(t *testing.T) {
	users := map[int]User{7: {Name: "Mina", Active: true}}
	got, ok := FindUser(users, 7)
	if !ok {
		t.Fatal("user 7 was not found")
	}
	if got.Name != "Mina" {
		t.Errorf("Name = %q; want Mina", got.Name)
	}
	if !got.Active {
		t.Error("Active = false; want true")
	}
}
```

**Run it**

```bash
go test ./...
```

After the lookup gateway, `got` is safe to dereference. The remaining checks do not depend on one another.

**validate.go**

```go
package lesson

import (
	"fmt"
	"sync"
)

func ValidateAll(values []int) []error {
	errs := make(chan error, len(values))
	var wg sync.WaitGroup
	for _, value := range values {
		value := value
		wg.Go(func() {
			if value < 0 {
				errs <- fmt.Errorf("negative value %d", value)
			}
		})
	}
	wg.Wait()
	close(errs)
	var result []error
	for err := range errs {
		result = append(result, err)
	}
	return result
}
```

**validate_test.go**

```go
package lesson

import "testing"

func TestValidateAll(t *testing.T) {
	errs := ValidateAll([]int{2, -1, 4})
	if len(errs) != 1 {
		t.Fatalf("got %d errors; want 1", len(errs))
	}
	if got := errs[0].Error(); got != "negative value -1" {
		t.Errorf("error = %q; want negative value -1", got)
	}
}
```

**Run it**

```bash
go test -race ./...
```

The concurrent function returns ordinary errors only after joining its workers. The test goroutine owns every testing method call.
